/**
 * @suppress
 */
public object FfiConverterTypePdfEngine: FfiConverter<PdfEngine, Pointer> {

    override fun lower(value: PdfEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): PdfEngine {
        return PdfEngine(value)
    }

    override fun read(buf: ByteBuffer): PdfEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: PdfEngine) = 8UL

    override fun write(value: PdfEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



