sealed class PdfException: kotlin.Exception() {
    
    class DatabaseException(
        
        val v1: kotlin.String
        ) : PdfException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class EngineException(
        
        val v1: kotlin.String
        ) : PdfException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class PasswordRequired(
        ) : PdfException() {
        override val message
            get() = ""
    }
    
    class InvalidSource(
        ) : PdfException() {
        override val message
            get() = ""
    }
    
    class PageOutOfBounds(
        
        val v1: kotlin.UInt
        ) : PdfException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class SearchCancelled(
        ) : PdfException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PdfException> {
        override fun lift(error_buf: RustBuffer.ByValue): PdfException = FfiConverterTypePdfError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypePdfError : FfiConverterRustBuffer<PdfException> {
    override fun read(buf: ByteBuffer): PdfException {
        

        return when(buf.getInt()) {
            1 -> PdfException.DatabaseException(
                FfiConverterString.read(buf),
                )
            2 -> PdfException.EngineException(
                FfiConverterString.read(buf),
                )
            3 -> PdfException.PasswordRequired()
            4 -> PdfException.InvalidSource()
            5 -> PdfException.PageOutOfBounds(
                FfiConverterUInt.read(buf),
                )
            6 -> PdfException.SearchCancelled()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PdfException): ULong {
        return when(value) {
            is PdfException.DatabaseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is PdfException.EngineException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is PdfException.PasswordRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is PdfException.InvalidSource -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is PdfException.PageOutOfBounds -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.v1)
            )
            is PdfException.SearchCancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: PdfException, buf: ByteBuffer) {
        when(value) {
            is PdfException.DatabaseException -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is PdfException.EngineException -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is PdfException.PasswordRequired -> {
                buf.putInt(3)
                Unit
            }
            is PdfException.InvalidSource -> {
                buf.putInt(4)
                Unit
            }
            is PdfException.PageOutOfBounds -> {
                buf.putInt(5)
                FfiConverterUInt.write(value.v1, buf)
                Unit
            }
            is PdfException.SearchCancelled -> {
                buf.putInt(6)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalFloat: FfiConverterRustBuffer<kotlin.Float?> {
    override fun read(buf: ByteBuffer): kotlin.Float? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterFloat.read(buf)
    }

    override fun allocationSize(value: kotlin.Float?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterFloat.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Float?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterFloat.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceUInt: FfiConverterRustBuffer<List<kotlin.UInt>> {
    override fun read(buf: ByteBuffer): List<kotlin.UInt> {
        val len = buf.getInt()
        return List<kotlin.UInt>(len) {
            FfiConverterUInt.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.UInt>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterUInt.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.UInt>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterUInt.write(it, buf)
        }
    }
}




